function longestPalindrome(s):
  start = 0, maxLen = 0
  for i = 0 to s.length - 1:
    len1 = expandAroundCenter(s, i, i)
    len2 = expandAroundCenter(s, i, i + 1)
    len = max(len1, len2)
    if len > maxLen:
      start = i - Math.floor((len - 1) / 2)
      maxLen = len
  return s.substring(start, start + maxLen)
